def build_prompt(docs, question):
    """docs: list of {"source": ..., "text": ...}. Documents first, question last."""
    parts = ["<documents>"]
    for doc in docs:
        parts.append(
            f"<document>\n<source>{doc['source']}</source>\n"
            f"<content>\n{doc['text']}\n</content>\n</document>"
        )
    parts.append("</documents>")
    parts.append("Answer using only the documents above. "
                 "If they do not contain the answer, reply NOT_FOUND.")
    parts.append(f"<question>{question}</question>")
    return "\n".join(parts)

import re

MARKDOWN_PATTERNS = [
    r"\*\*[^*]+\*\*",    # **bold**
    r"^\s*#{1,6}\s",      # heading at the start of a line
    r"^\s*\|.*\|\s*$",    # | table | row |
]


def has_markdown(text):
    """True when a WhatsApp reply contains Markdown that would show as raw symbols."""
    return any(re.search(p, text, flags=re.MULTILINE) for p in MARKDOWN_PATTERNS)
